// GridSiteTrust Trust policy for this site.
// When configured, the operator verifies the received public certificate against this policy before promoting the site to Active. If absent, the site remains Connecting with reason TrustMaterialMissing regardless of certificate material.
type GridSiteTrust struct {
	// Canonical DER-certificate SHA-256 fingerprint pins.
	// Each entry is a 64-character lowercase hex string computed as hex(sha256(der_bytes)) where der_bytes are the raw DER encoding of the leaf certificate.
	// At most two entries are allowed: the current pin and an optional next pin for bounded rotation overlap. The probe succeeds if the peer leaf certificate matches **any** entry in this list.
	CanonicalFingerprints []string `json:"canonicalFingerprints,omitempty"`
	// Legacy SHA-256 fingerprint of the remote site's public certificate PEM.
	// Format: colon-separated lowercase hex bytes, e.g. "ab:cd:ef:...". Computed as sha256(pem_bytes) where pem_bytes are the UTF-8 bytes of status.publicCertPem.
	// **Deprecated:** use canonicalFingerprints for new deployments. The two fields must not both be set.
	CertFingerprint *string `json:"certFingerprint,omitempty"`
}

