// HealthCheckConfig Health check configuration.
type HealthCheckConfig struct {
	// Base URL for health probes, independent of spec.endpoint.
	// When set, the probe URL is {endpoint}{path} instead of {spec.endpoint}{path}. This allows probing a separate service (such as an llm-d EPP) while the provider inference endpoint points at the pool's request path.
	// When absent, the probe URL uses spec.endpoint as before.
	Endpoint *string `json:"endpoint,omitempty"`
	// Check interval (e.g. "30s").
	Interval *string `json:"interval,omitempty"`
	// HTTP path for health probes.
	Path *string `json:"path,omitempty"`
	// Timeout per check (e.g. "5s").
	Timeout *string `json:"timeout,omitempty"`
	// Optional TLS override for the health probe endpoint.
	// When absent, InferenceProvider.spec.tls is used when configured; otherwise, the probe uses system root certificates. Set this only when the health endpoint requires different trust material or a different client identity.
	// **Fail-closed:** when configured but the referenced Secrets cannot be resolved or contain invalid material, the probe is skipped entirely. The operator never falls back to system roots or plain HTTP.
	TLS *EndpointTLSConfig `json:"tls,omitempty"`
}

// MetricsAuth How the scraper authenticates to the metrics endpoint. Absent sends no credential.
type MetricsAuth struct {
	// Send the credential over plain http://. Off by default, because a bearer token on an unencrypted connection can be read off the network. For a lab only.
	AllowPlaintext *bool `json:"allowPlaintext,omitempty"`
	// The credential to send.
	Type MetricsAuthType `json:"type"`
}

// MetricSignalNames Mapping from scoring signal names to Prometheus metric names.
// Signals without a configured name are skipped during parsing and receive the neutral default value (0.5) in scoring.
type MetricSignalNames struct {
	// Metric name for normalised error rate (0.0 to 1.0).
	ErrorRate *string `json:"errorRate,omitempty"`
	// Metric name for a health gauge (any positive value = healthy).
	Healthy *string `json:"healthy,omitempty"`
	// Metric name for KV-cache utilisation (0.0 to 1.0).
	KVCacheUtilization *string `json:"kvCacheUtilization,omitempty"`
	// Metric name for P99 request latency in milliseconds (pre-computed gauge).
	LatencyP99Ms *string `json:"latencyP99Ms,omitempty"`
	// Metric name for prefix-cache hit ratio (0.0 to 1.0).
	PrefixCacheHitRatio *string `json:"prefixCacheHitRatio,omitempty"`
	// Metric name for normalised queue depth (0.0 to 1.0).
	QueueDepth *string `json:"queueDepth,omitempty"`
	// Metric name counting the pool's ready endpoints, read for the Ready condition.
	// Defaults to llm_d_epp_ready_endpoints, then inference_pool_ready_pods. Filtered by poolName when set. Zero marks the provider not ready.
	ReadyEndpoints *string `json:"readyEndpoints,omitempty"`
}

// MetricsConfig Prometheus metrics scraping configuration.
// When set, the Grid operator scrapes the provider's metrics endpoint during each [GridNetwork] reconcile and incorporates the parsed signals into the routing overlay scoring pass. When absent, the provider uses locality and cost as the only scoring signals (static ordering).
// [GridNetwork]: crate::crd::grid_network::GridNetwork
type MetricsConfig struct {
	// How the scraper authenticates to the metrics endpoint. Absent sends no credential.
	Auth *MetricsAuth `json:"auth,omitempty"`
	// Base URL for the metrics endpoint, independent of spec.endpoint.
	// When set, the scrape URL is {endpoint}{path} instead of {spec.endpoint}{path}. This allows scraping metrics from a separate service (such as an llm-d EPP) while the provider inference endpoint points at the pool's request path.
	// When absent, the scrape URL uses spec.endpoint as before.
	Endpoint *string `json:"endpoint,omitempty"`
	// HTTP path for the Prometheus metrics endpoint.
	// Appended to endpoint (when set) or spec.endpoint. Defaults to "/metrics" when absent.
	Path *string `json:"path,omitempty"`
	// Expected Prometheus name label value for pool-level metric selection.
	// When set, the parser only matches metric samples whose name label equals this value. This is required when scraping an endpoint that exposes metrics for multiple pools (such as an llm-d EPP), ensuring the configured pool is selected deterministically.
	// The parser rejects the scrape when the expected pool series is absent or when a metric sample has no name label and this field is set.
	// When absent, labels are stripped before matching as in v1 (backward compatible).
	PoolName *string `json:"poolName,omitempty"`
	// Maximum queue slot count for normalising a raw queue-size metric to the 0.0 to 1.0 range.
	// When set, the queue_depth signal value is divided by this capacity and clamped to [0.0, 1.0] before scoring. This allows consuming raw average queue-size metrics (such as llm_d_epp_average_queue_size) without requiring the exporter to pre-normalise.
	// When absent, the queue_depth signal must already be normalised to the 0.0 to 1.0 range by the exporter (backward compatible).
	QueueCapacity *int64 `json:"queueCapacity,omitempty"`
	// Mapping from scoring signal names to Prometheus metric names.
	// Signals without a configured name are skipped during parsing and receive the neutral default value (0.5) in scoring.
	SignalNames *MetricSignalNames `json:"signalNames,omitempty"`
	// Maximum age in seconds for which a previously-scraped metric sample may be used when the current scrape fails.
	// When a Prometheus scrape fails (connection refused, timeout, HTTP error), setting this field enables a grace period: if the last *successful* scrape is no older than stale_metrics_seconds, that cached sample is reused.
	// For plaintext metrics, after the grace period expires or before any successful scrape, metrics fall back to neutral scoring. When TLS is configured, the same condition marks the provider unhealthy and excludes it from routing.
	// **Default (absent):** no grace period. Plaintext scrape failures immediately produce neutral scoring; TLS-configured failures without a cached sample fail closed.
	// **Minimum value:** 1 second. The schema rejects 0; the operator also treats zero defensively as absent.
	StaleMetricsSeconds *int64 `json:"staleMetricsSeconds,omitempty"`
	// Per-request scrape timeout (e.g. "2s", "500ms").
	// Defaults to "2s". Only s and ms suffixes are recognised; unrecognised values fall back to the default.
	Timeout *string `json:"timeout,omitempty"`
	// Optional TLS override for the metrics endpoint.
	// When absent, InferenceProvider.spec.tls is used when configured; otherwise, the scraper uses system root certificates. Set this only when the metrics endpoint requires different trust material or a different client identity.
	// **Fail-closed:** when configured but the referenced Secrets cannot be resolved or contain invalid material, the scrape is skipped entirely. The scraper never falls back to system roots or plain HTTP.
	TLS *EndpointTLSConfig `json:"tls,omitempty"`
	// Deprecated in favor of endpoint; this legacy field will be removed in a future release. Base URL for the metrics endpoint, independent of spec.endpoint.
	// When set, the scrape URL is {endpoint}{path} instead of {spec.endpoint}{path}. This allows scraping metrics from a separate service (such as an llm-d EPP) while the provider inference endpoint points at the pool's request path.
	// When absent, the scrape URL uses spec.endpoint as before.
	MetricsEndpoint *string `json:"metricsEndpoint,omitempty"`
}

// OpenAIModelsSource OpenAI-compatible GET /v1/models (vLLM, KServe, OpenAI).
// Reads data[].id from the response. The response is rejected as a whole when it is not valid JSON, has a blank, overlong, or duplicate id, or lists more models than the operator's cap. A rejected response never clears the previously discovered set.
type OpenAIModelsSource struct {
	// Base URL; defaults to spec.endpoint.
	Endpoint *string `json:"endpoint,omitempty"`
	// Path appended to the base URL.
	Path *string `json:"path,omitempty"`
	// Optional TLS override for the model-listing endpoint.
	// When absent, InferenceProvider.spec.tls is used when configured; otherwise, system root certificates are used. Set this only when the model-listing endpoint requires different trust material or a different client identity.
	TLS *EndpointTLSConfig `json:"tls,omitempty"`
}

// ModelDiscoveryConfig Where to discover the models this provider serves.
// When set, the operator polls the backend on a fixed cadence and holds the served-model set in memory, expiring it when polls stop succeeding. Until route and provider-record formats support inventory expiry, discovered names are withheld and do not fall back to spec.models. When absent, no discovery runs. Exactly one source field must be set (CRD oneOf).
type ModelDiscoveryConfig struct {
	// OpenAI-compatible GET /v1/models (vLLM, KServe, OpenAI).
	// Reads data[].id from the response. The response is rejected as a whole when it is not valid JSON, has a blank, overlong, or duplicate id, or lists more models than the operator's cap. A rejected response never clears the previously discovered set.
	OpenAIModels *OpenAIModelsSource `json:"openAiModels,omitempty"`
}

// ModelInfo Model metadata for an inference provider.
type ModelInfo struct {
	// Supported capabilities.
	Capabilities []string `json:"capabilities,omitempty"`
	// Maximum context window size.
	ContextWindow *int64 `json:"contextWindow,omitempty"`
	// Model name.
	Name string `json:"name"`
}

// TrafficPolicy Optional administrative traffic policy.
type TrafficPolicy struct {
	// Stop new sessions while preserving existing affinity sessions.
	Drain bool `json:"drain,omitempty"`
}

// InferenceProviderSpec Specification for an [InferenceProvider].
type InferenceProviderSpec struct {
	// Which sites can consume this provider.
	AccessPolicy *AccessPolicy `json:"accessPolicy,omitempty"`
	// Authentication configuration.
	Auth *AuthConfig `json:"auth,omitempty"`
	// Backend deployment category.
	BackendKind string `json:"backendKind"`
	// Relative capacity used by an opt-in placement policy.
	CapacityWeight *int64 `json:"capacityWeight,omitempty"`
	// Optional routing identity used in overlay candidate site and cluster fields.
	// When set, routing overlay candidates produced for this provider use this value instead of metadata.name:
	// - In Phase 1 (no [GridSite] inventory), both candidate.site and candidate.cluster are set to this value. - When [GridSite] resources are present, only candidate.cluster is overridden; candidate.site is derived from the matched GridSite.
	// Use this to align the provider's routing identity with an upstream cluster name already configured in the consumer gateway, such as a Praxis load_balancer cluster entry. When absent, metadata.name is used.
	// [GridSite]: crate::crd::grid_site::GridSite
	ClusterName *string `json:"clusterName,omitempty"`
	// Cost information.
	Cost *CostConfig `json:"cost,omitempty"`
	// HTTP endpoint URL.
	Endpoint string `json:"endpoint"`
	// Name of the [GridNetwork] this provider belongs to.
	// [GridNetwork]: crate::crd::grid_network::GridNetwork
	GridNetworkRef string `json:"gridNetworkRef"`
	// Health check configuration.
	HealthCheck *HealthCheckConfig `json:"healthCheck,omitempty"`
	// Prometheus metrics scraping configuration.
	// When set, the Grid operator scrapes the provider's metrics endpoint during each [GridNetwork] reconcile and incorporates the parsed signals into the routing overlay scoring pass. When absent, the provider uses locality and cost as the only scoring signals (static ordering).
	// [GridNetwork]: crate::crd::grid_network::GridNetwork
	MetricsConfig *MetricsConfig `json:"metricsConfig,omitempty"`
	// Where to discover the models this provider serves.
	// When set, the operator polls the backend on a fixed cadence and holds the served-model set in memory, expiring it when polls stop succeeding. Until route and provider-record formats support inventory expiry, discovered names are withheld and do not fall back to spec.models. When absent, no discovery runs.
	ModelDiscovery *ModelDiscoveryConfig `json:"modelDiscovery,omitempty"`
	// Models served by this provider.
	Models []ModelInfo `json:"models,omitempty"`
	// Stable provider-gateway identity used by administrative operations.
	// Providers with the same value are drained together by the gateway-wide operation. It is an explicit control-plane relationship; the operator never infers it from endpoint URLs.
	ProviderGateway *string `json:"providerGateway,omitempty"`
	// Inference provider type.
	ProviderKind string `json:"providerKind"`
	// Which sites host this provider.
	SiteSelector *SelectorConfig `json:"siteSelector,omitempty"`
	// Shared TLS configuration for provider health checks, metrics scraping, and model discovery.
	// A feature-specific tls setting overrides this value when it needs a different CA bundle or client identity. When neither is set, the request uses system root certificates.
	TLS *EndpointTLSConfig `json:"tls,omitempty"`
	// Optional administrative traffic policy.
	TrafficPolicy *TrafficPolicy `json:"trafficPolicy,omitempty"`
	// Deprecated in favor of providerGateway; this legacy field will be removed in a future release. Stable provider-gateway identity used by administrative operations.
	// Providers with the same value are drained together by the gateway-wide operation. It is an explicit control-plane relationship; the operator never infers it from endpoint URLs.
	GatewayRef *string `json:"gatewayRef,omitempty"`
	// Deprecated in favor of clusterName; this legacy field will be removed in a future release. Optional routing identity used in overlay candidate site and cluster fields.
	// When set, routing overlay candidates produced for this provider use this value instead of metadata.name:
	// - In Phase 1 (no [GridSite] inventory), both candidate.site and candidate.cluster are set to this value. - When [GridSite] resources are present, only candidate.cluster is overridden; candidate.site is derived from the matched GridSite.
	// Use this to align the provider's routing identity with an upstream cluster name already configured in the consumer gateway, such as a Praxis load_balancer cluster entry. When absent, metadata.name is used.
	// [GridSite]: crate::crd::grid_site::GridSite
	RoutingClusterRef *string `json:"routingClusterRef,omitempty"`
}

// InferenceProviderStatus Observed status of an [InferenceProvider].
type InferenceProviderStatus struct {
	// Observed conditions. Ready says whether the provider can currently serve a request.
	// Written by the operator's signals loop, never by provider reconciliation.
	Conditions []metav1.Condition `json:"conditions,omitempty"`
	// Sites matched by the site selector.
	MatchingSites []string `json:"matchingSites,omitempty"`
	// Bounded reason for the latest model-discovery failure, absent after a successful poll.
	ModelDiscoveryError *string `json:"modelDiscoveryError,omitempty"`
	// Effective model-listing URL when discovery is configured.
	// This is the requested URL, not an indication that polling succeeded.
	ModelDiscoveryURL *string `json:"modelDiscoveryUrl,omitempty"`
	// Last observed generation.
	ObservedGeneration int64 `json:"observedGeneration,omitempty"`
	// Current phase.
	Phase ProviderPhase `json:"phase,omitempty"`
	// Machine-readable reason for the current phase when not Available.
	// Set when the provider cannot reach Available due to a configuration, credential, or metrics/health-check collection error. None when the provider is Available, Pending, or the reason is unknown.
	// Stable reason values: - UnsupportedAuthStrategy, CredentialSecretRefInvalid, CredentialSecretMissing, CredentialSecretKeyMissing, CredentialSecretValueInvalid - MetricsTlsSecretMissing, MetricsTlsKeyMissing, MetricsTlsMaterialInvalid, MetricsTlsIdentityMismatch - HealthCheckTlsSecretMissing, HealthCheckTlsKeyMissing, HealthCheckTlsMaterialInvalid, HealthCheckTlsIdentityMismatch - HealthCheckAuthCredentialUnavailable, HealthCheckAuthValueInvalid
	Reason *string `json:"reason,omitempty"`
	// Models the discovery loop last observed this provider serving.
	// Present for a successful held set. Cleared when the set is unknown, expired, or discovery is disabled, though clearing may lag after expiry. Readers must require servedModelsExpiresAt to be in the future. An empty set means the backend serves no models. Bounded by the discovery caps (256 models, 256-byte names); order carries no meaning.
	ServedModels []string `json:"servedModels,omitempty"`
	// RFC 3339 UTC deadline for the corresponding servedModels set.
	// Readers must reject the set at or after this time, even if the status field has not yet been cleared by the next discovery round.
	ServedModelsExpiresAt *string `json:"servedModelsExpiresAt,omitempty"`
	// Provider generation that produced the corresponding servedModels set.
	// Readers must require this value to equal metadata.generation; a spec change invalidates the inventory until discovery succeeds again.
	ServedModelsObservedGeneration *int64 `json:"servedModelsObservedGeneration,omitempty"`
}

// SiteInviteSpec An invitation that authorizes one site to request admission.
type SiteInviteSpec struct {
	// Whether a deleted site name may enroll again.
	AllowDeletedName bool `json:"allowDeletedName,omitempty"`
	// Jurisdiction labels assigned to the site.
	Jurisdictions []string `json:"jurisdictions"`
	// Optional lifetime, from 5m through 168h.
	Lifetime *string `json:"lifetime,omitempty"`
	// Optional SHA-256 digest of the bound public key.
	PublicKeySHA256 *string `json:"publicKeySHA256,omitempty"`
	// Site name pinned by the signer.
	SiteName string `json:"siteName"`
}

// SecretKeyRef Secret containing the one-time token.
type SecretKeyRef struct {
	// Data key holding the token.
	Key string `json:"key"`
	// Secret name.
	Name string `json:"name"`
	// Secret namespace.
	Namespace string `json:"namespace"`
}

// SiteInviteStatus Observed invitation state.
type SiteInviteStatus struct {
	// Standard condition-shaped lifecycle status.
	Conditions []metav1.Condition `json:"conditions,omitempty"`
	// Token expiry in RFC 3339 format.
	ExpiresAt *string `json:"expiresAt,omitempty"`
	// Last observed generation.
	ObservedGeneration int64 `json:"observedGeneration,omitempty"`
	// Public key digest accepted by the signer.
	PublicKeySHA256 *string `json:"publicKeySHA256,omitempty"`
	// CSR name that redeemed this invitation.
	RedeemedBy *string `json:"redeemedBy,omitempty"`
	// Secret containing the one-time token.
	SecretRef *SecretKeyRef `json:"secretRef,omitempty"`
	// Public token identifier; the token secret is never stored here.
	TokenID *string `json:"tokenId,omitempty"`
}
